// Basic Type Aliasing with typedef
typedef unsigned long ULONG;

// Aliasing a pointer type (safe for multiple declarations)
typedef char* C_STRING;

// Aliasing an array type
typedef int MatrixRow[10];

ULONG device_id = 999;
C_STRING name_1, name_2; // both are char*
MatrixRow row_data;


// Typedef for Function Pointers (Callback Abstraction)
// Define signature: int func(void*, size_t)
typedef int (*CleanupHandler)(void*, size_t);

// Function implementation
int free_buffer(void* data, size_t size) { /* ... */ return 0; }

// Use the alias
CleanupHandler handler = &free_buffer;
int status = handler(NULL, 1024);


// Using #define for Abstraction (Preprocessor substitution)
#define MAX_SIZE_T unsigned long long
#define PTR_TO_INT int*

MAX_SIZE_T limit = 1000;

// Caution: #define does not handle pointer declaration safely
PTR_TO_INT pA, pB; // Expands to: int* pA, pB; (pB is int)

// Use typedef for safe pointer aliasing
typedef int* Safe_PTR_INT;
Safe_PTR_INT pC, pD; // pC and pD are both int*
